const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const jaenPoint = ee.Geometry.Point(-3.79, 37.77); // Approximate coordinates for Jaén, Spain
  const region = jaenPoint.buffer(5000); // A 5km buffer around Jaén to represent "a few miles east of Córdoba"

  const startDate = '2023-01-01';
  const endDate = '2023-05-16'; // Includes data up to May 15th

  // 2. Data Acquisition & Check
  // Using CHIRPS Daily precipitation data (mm per day)
  let chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  const initialSize = await chirps.size().getInfo();
  if (initialSize === 0) {
    console.log("No CHIRPS images found for the specified date range and location.");
    console.log("C1");
    return;
  }

  // Select the 'precipitation' band, which is daily precipitation in mm
  const precipitationCollection = chirps.select('precipitation');

  // Calculate total precipitation over the period
  const totalPrecipitationImage = precipitationCollection.sum();

  // 3. Processing & Calculation
  // Reduce the total precipitation image to get the mean precipitation within the region
  // Using a relatively large scale to avoid timeout, as required (e.g., 1000m)
  const stats = await totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000, // 1 km scale
    maxPixels: 1e9
  }).getInfo();

  const totalPrecipitationMm = stats && stats.precipitation;

  // Validate the result
  if (totalPrecipitationMm === null || isNaN(totalPrecipitationMm)) {
    console.log("Calculation failed: result is None or NaN.");
    console.log("C3");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const totalPrecipitationInches = totalPrecipitationMm / 25.4;

  // Target threshold: 3 inches
  const thresholdInches = 3;

  console.log(`Initial CHIRPS images: ${initialSize}`);
  console.log(`Total precipitation in Jaén region (Jan 1 - May 15, 2023): ${totalPrecipitationInches.toFixed(2)} inches`);

  // 4. Validation & Final Answer
  if (totalPrecipitationInches > thresholdInches) {
    console.log("A"); // Yes, it received more than 3 inches
  } else {
    console.log("B"); // No, it did not receive more than 3 inches
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
